head.script:
scwin.onpageload = function() {
	var rowJSON = {
		"addr": "서울시",
		"name": "손예진",
		"rowStatus": "R"
	};
	var dataObj = {
		type: "json",
		data: rowJSON,
		name: "rowObj"
	};
	var options = {
		id: "popup1",
		type: "litewindow",
		width: "230px",
		height: "250px",
		top: "130px",
		left: "200px",
		popupName: "openPopup1",
		modal: false,
		resizable: true,
		status: true,
		menubar: false,
		scrollbars: false,
		title: true,
		dataObject: dataObj
	};
	$w.openPopup("/sample/common_link/p_popup_TitleBar_SKT-735_(WSQ-2590)_popup.xml", options);
};
